const cfg = $('Config').first().json;
const tz = cfg.timezone || 'UTC';
const now = DateTime.now().setZone(tz);
const norm = s => String(s ?? '').trim();
const low = s => norm(s).toLowerCase();

// ---------- 1. Resolve the Postiz channels ----------
let ints = $('Postiz — List Channels').all().map(i => i.json);
if (ints.length === 1 && Array.isArray(ints[0].integrations)) ints = ints[0].integrations;
ints = ints.filter(x => x && x.id);
const ident = x => low(x.identifier || x.providerIdentifier || x.provider);
const findChannel = (types, pinned) => pinned
  ? (ints.find(x => x.id === pinned) || null)
  : (ints.find(x => types.includes(ident(x)) && !x.disabled) || null);

const channels = {};
if (cfg.platforms.includes('facebook')) {
  const c = findChannel(['facebook'], cfg.facebook_integration_id);
  if (c) channels.facebook = c;
}
if (cfg.platforms.includes('instagram')) {
  const c = findChannel(['instagram', 'instagram-standalone'], cfg.instagram_integration_id);
  if (c) channels.instagram = c;
}
if (!Object.keys(channels).length) {
  throw new Error('No Facebook/Instagram channel found in Postiz. Channels seen: ' +
    (ints.map(x => ident(x) + ' (' + x.name + ')').join(', ') || 'none - check postiz_base and the Postiz API key'));
}
const plats = Object.keys(channels);

// ---------- 2. Rows that are ready to publish ----------
const rows = $('Read Posts Pending').all().map(i => i.json);
const allowed = cfg.require_approval ? ['approved'] : ['pending', 'approved'];
const eligible = rows
  .filter(r =>
    norm(r.Content_ID) &&
    allowed.includes(low(r.Status)) &&
    /^https?:\/\//.test(norm(r.KIE_Image_URL)) &&
    (norm(r.Facebook_Post) || norm(r.Instagram_Caption)) &&
    !norm(r.Postiz_IDs))
  .sort((a, b) =>
    (Number(b.Awareness_Score) || 0) - (Number(a.Awareness_Score) || 0) ||
    String(a.Date).localeCompare(String(b.Date)));
if (!eligible.length) return [];

// ---------- 3. Next free slots (continues after what is already queued) ----------
const at = (day, hhmm) => {
  const [h, m] = String(hhmm).split(':').map(Number);
  return day.set({ hour: h || 0, minute: m || 0, second: 0, millisecond: 0 });
};
const parse = v => {
  if (!norm(v)) return null;
  const d = DateTime.fromISO(norm(v), { setZone: true });
  return d.isValid ? d : null;
};
let lastQueued = null;
for (const r of rows) {
  const t = [parse(r.FB_Scheduled_For), parse(r.IG_Scheduled_For)].filter(Boolean);
  if (!t.length) continue;
  const anchor = DateTime.min(...t);
  if (!lastQueued || anchor > lastQueued) lastQueued = anchor;
}

const jitter = () => Math.floor(Math.random() * ((Number(cfg.jitter_minutes) || 0) + 1));
const perDay = Math.max(1, Math.min(cfg.facebook_times.length, cfg.instagram_times.length));
const maxRows = Math.max(1, Number(cfg.posts_per_run) || 1);
const slots = [];
if (cfg.post_type === 'now') {
  slots.push({ facebook: now, instagram: now }); // never blast several posts at once
} else {
  for (let d = 0; d <= cfg.max_days_ahead && slots.length < maxRows; d++) {
    const day = now.startOf('day').plus({ days: d });
    for (let s = 0; s < perDay && slots.length < maxRows; s++) {
      const base = { facebook: at(day, cfg.facebook_times[s]), instagram: at(day, cfg.instagram_times[s]) };
      const anchor = DateTime.min(...plats.map(p => base[p]));
      if (anchor <= now.plus({ minutes: 15 })) continue;
      if (lastQueued && anchor <= lastQueued) continue;
      slots.push({
        facebook: base.facebook.plus({ minutes: jitter() }),
        instagram: base.instagram.plus({ minutes: jitter() })
      });
    }
  }
}
if (!slots.length) return []; // queue is already full for max_days_ahead

// ---------- 4. Platform-specific copy ----------
const GENERIC = new Set(['#travel', '#wellness', '#wanderlust', '#explore', '#nature', '#travelgram',
  '#instatravel', '#travelphotography', '#vacation', '#holiday', '#trip', '#instagood', '#photooftheday',
  '#selfcare', '#health', '#relax', '#yoga', '#spa', '#mindfulness', '#travelblogger', '#adventure']);

const parseTags = s => {
  const seen = new Set();
  return (norm(s).match(/#?[\p{L}\p{N}_]+/gu) || [])
    .map(t => '#' + t.replace(/^#/, ''))
    .filter(t => { const k = low(t); if (seen.has(k)) return false; seen.add(k); return true; });
};

// 1 broad tag for reach, the rest niche (niche tags rank better), brand tag last
const chooseTags = (all, max) => {
  const brand = norm(cfg.brand_hashtag) ? [norm(cfg.brand_hashtag)] : [];
  const pool = all.filter(t => !brand.some(b => low(b) === low(t)));
  const niche = pool.filter(t => !GENERIC.has(low(t)));
  const broad = pool.filter(t => GENERIC.has(low(t)));
  const room = Math.max(0, max - brand.length);
  let picked = niche.slice(0, Math.max(0, room - 1));
  picked = picked.concat(broad.slice(0, room - picked.length));
  for (const t of niche) { if (picked.length >= room) break; if (!picked.includes(t)) picked.push(t); }
  return [...picked.slice(0, room), ...brand].slice(0, max);
};

// remove hashtag-only lines, un-hash inline tags (we add our own curated set)
const stripTags = text => norm(text).split('\n')
  .filter(line => !/^\s*(#[\p{L}\p{N}_]+[\s,.]*)+$/u.test(line))
  .join('\n')
  .replace(/#([\p{L}\p{N}_]+)/gu, '$1')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const instagramCaption = (r, tags) => {
  let body = stripTags(r.Instagram_Caption || r.Facebook_Post);
  const hook = norm(r.Hook);
  const first = body.split('\n')[0] || '';
  // Instagram cuts the caption at ~125 chars ("... more"): the hook must fit before that
  if (hook && first.length > 125 && hook.length <= 125 && !low(body).includes(low(hook))) body = hook + '\n\n' + body;
  const cta = stripTags(r.CTA);
  if (cta && !low(body).includes(low(cta).slice(0, 25))) body += '\n\n' + cta;
  const tagLine = tags.join(' ');
  const maxBody = 2200 - tagLine.length - 4;
  if (body.length > maxBody) body = body.slice(0, maxBody - 1).replace(/\s+\S*$/, '') + '…';
  return (body + (tagLine ? '\n\n' + tagLine : '')).trim();
};

const facebookPost = (r, tags) => {
  let body = stripTags(r.Facebook_Post || r.Instagram_Caption);
  // links in the post body cut Facebook reach -> the link goes in the first comment instead
  body = body.replace(/[ \t]*https?:\/\/\S+/g, '').replace(/[ \t]+\n/g, '\n').trim();
  return (body + (tags.length ? '\n\n' + tags.join(' ') : '')).trim();
};

const iso = d => d.toISO({ suppressMilliseconds: true });

return eligible.slice(0, slots.length).map((r, i) => {
  const slot = slots[i];
  const all = parseTags(r.Hashtags);
  const posts = [];
  if (channels.facebook) posts.push({
    platform: 'facebook',
    integration_id: channels.facebook.id,
    settings: { __type: 'facebook' },
    content: facebookPost(r, chooseTags(all, cfg.facebook_max_hashtags)),
    comment: norm(cfg.facebook_link) ? 'Full guide here: ' + norm(cfg.facebook_link) : '',
    date_utc: iso(slot.facebook.toUTC()),
    date_local: iso(slot.facebook)
  });
  if (channels.instagram) posts.push({
    platform: 'instagram',
    integration_id: channels.instagram.id,
    settings: { __type: ident(channels.instagram) || 'instagram', post_type: 'post', is_trial_reel: false, collaborators: [] },
    content: instagramCaption(r, chooseTags(all, cfg.instagram_max_hashtags)),
    comment: '',
    date_utc: iso(slot.instagram.toUTC()),
    date_local: iso(slot.instagram)
  });
  return { json: {
    content_id: norm(r.Content_ID),
    row_number: r.row_number,
    topic: r.Topic,
    awareness_score: r.Awareness_Score,
    image_url: norm(r.KIE_Image_URL),
    posts
  }};
});

const cfg = $('Config').first().json;
const match = (node, i) => { try { return $(node).itemMatching(i).json; } catch (e) { return $(node).all()[i].json; } };

const out = [];
$input.all().forEach((it, i) => {
  const row = match('Pick Rows + Plan Slots', i);
  const up = it.json || {};
  if (up.error || !up.path) {
    const msg = up.error ? (up.error.message || JSON.stringify(up.error)) : JSON.stringify(up).slice(0, 200);
    out.push({ json: { ready: false, content_id: row.content_id,
      error: 'Image upload to Postiz failed (KIE image URLs expire after ~14 days - regenerate the image): ' + msg } });
    return;
  }
  const image = [{ id: up.id, path: up.path }];
  for (const p of row.posts) {
    const value = [{ content: p.content, image }];
    if (p.comment) value.push({ content: p.comment, image: [] }); // 2nd value = first comment
    out.push({ json: {
      ready: true,
      content_id: row.content_id,
      platform: p.platform,
      scheduled_for: cfg.post_type === 'now' ? '' : p.date_local,
      postBody: {
        type: cfg.post_type,
        date: p.date_utc,
        shortLink: false,
        tags: [],
        posts: [{ integration: { id: p.integration_id }, value, settings: p.settings }]
      }
    }});
  }
});
return out;

const cfg = $('Config').first().json;
const match = (node, i) => {
  try { return $(node).itemMatching(i).json; }
  catch (e) { return $(node).all().map(x => x.json).filter(x => x.ready)[i]; }
};

const groups = {};
$input.all().forEach((it, i) => {
  const req = match('Build Postiz Requests', i);
  const r = it.json || {};
  const id = r.postId || r.id || '';
  const err = r.error
    ? (r.error.message || r.error.description || JSON.stringify(r.error))
    : (!id ? 'no post id returned: ' + JSON.stringify(r).slice(0, 200) : '');
  const g = groups[req.content_id] = groups[req.content_id] || { content_id: req.content_id, res: [] };
  g.res.push({ platform: req.platform, ok: !err, id, when: req.scheduled_for, err });
});

const okWord = { schedule: 'Scheduled', now: 'Posted', draft: 'Postiz Draft' }[cfg.post_type] || 'Scheduled';
const stamp = DateTime.now().setZone(cfg.timezone || 'UTC').toFormat('yyyy-MM-dd HH:mm');

return Object.values(groups).map(g => {
  const ok = g.res.filter(x => x.ok);
  const bad = g.res.filter(x => !x.ok);
  const when = p => (g.res.find(x => x.platform === p && x.ok) || {}).when || '';
  return { json: {
    Content_ID: g.content_id,
    Status: !bad.length ? okWord : (ok.length ? 'Partial - check Postiz' : 'Error'),
    FB_Scheduled_For: when('facebook'),
    IG_Scheduled_For: when('instagram'),
    Postiz_IDs: ok.map(x => x.platform + ':' + x.id).join(' | '),
    Publish_Log: stamp + ' | ' + g.res.map(x => x.platform + (x.ok ? ' OK ' + (x.when || 'now') : ' FAILED ' + x.err)).join(' | ')
  }};
});

const cfg = $('Config').first().json;
const stamp = DateTime.now().setZone(cfg.timezone || 'UTC').toFormat('yyyy-MM-dd HH:mm');
return $input.all().map(i => ({ json: {
  Content_ID: i.json.content_id,
  Status: 'Error',
  FB_Scheduled_For: '',
  IG_Scheduled_For: '',
  Postiz_IDs: '',
  Publish_Log: stamp + ' | ' + i.json.error
}}));
